import { formatDuration } from "./duration";

const s = 1000;
const m = 60 * s;
const h = 60 * m;
const d = 24 * h;

describe("formatDuration", () => {
  it("formats anything under a second as 0s", () => {
    expect(formatDuration(0)).toBe("0s");
    expect(formatDuration(999)).toBe("0s");
  });

  it("formats seconds", () => {
    expect(formatDuration(45 * s)).toBe("45s");
  });

  it("shows the largest unit and the next one down", () => {
    expect(formatDuration(3 * m + 20 * s)).toBe("3m 20s");
    expect(formatDuration(h + 5 * m)).toBe("1h 5m");
    expect(formatDuration(2 * d + 3 * h)).toBe("2d 3h");
  });

  it("omits the next unit when it is zero", () => {
    expect(formatDuration(2 * d)).toBe("2d");
    expect(formatDuration(h + 30 * s)).toBe("1h");
  });

  it("drops smaller units instead of rounding", () => {
    expect(formatDuration(h + 5 * m + 59 * s)).toBe("1h 5m");
  });

  it("rejects negative and non-finite durations", () => {
    expect(() => formatDuration(-1)).toThrow(RangeError);
    expect(() => formatDuration(NaN)).toThrow(RangeError);
    expect(() => formatDuration(Infinity)).toThrow(RangeError);
  });
});

describe("formatDuration, more cases (trial T4, turn 1)", () => {
  it("keeps only the two largest units", () => {
    expect(formatDuration(d + h + m + s)).toBe("1d 1h");
  });

  it("rounds down to whole seconds", () => {
    expect(formatDuration(59 * s + 999)).toBe("59s");
    expect(formatDuration(m)).toBe("1m");
  });
});

import { formatDuration } from "./duration";

const s = 1000;
const m = 60 * s;
const h = 60 * m;
const d = 24 * h;

describe("formatDuration long (trial T4, turn 2)", () => {
  it("spells units out and pluralizes them", () => {
    expect(formatDuration(h + 5 * m, { long: true })).toBe("1 hour 5 minutes");
    expect(formatDuration(2 * d, { long: true })).toBe("2 days");
    expect(formatDuration(d + h, { long: true })).toBe("1 day 1 hour");
    expect(formatDuration(s, { long: true })).toBe("1 second");
    expect(formatDuration(0, { long: true })).toBe("0 seconds");
  });

  it("keeps the short form by default", () => {
    expect(formatDuration(h + 5 * m)).toBe("1h 5m");
  });
});
